// ==== Instellingen (v3.1) ====
// Optioneel overschrijven via Node-RED env:
//   MODBUS_LISTEN_HOST, MODBUS_LISTEN_PORT, MODBUS_TARGET_HOST, MODBUS_TARGET_PORT
function envStr(name, fallback) {
    try {
        if (typeof env !== 'undefined' && typeof env.get === 'function') {
            const v = env.get(name);
            if (v !== undefined && v !== null && String(v) !== '') return String(v);
        }
    } catch (e) { /* geen env-context */ }
    return fallback;
}

function envInt(name, fallback) {
    const v = parseInt(envStr(name, String(fallback)), 10);
    return Number.isFinite(v) ? v : fallback;
}

const LISTEN_HOST = envStr('MODBUS_LISTEN_HOST', '0.0.0.0');
const LISTEN_PORT = envInt('MODBUS_LISTEN_PORT', 1502);
const TARGET_HOST = envStr('MODBUS_TARGET_HOST', '172.19.211.243');
const TARGET_PORT = envInt('MODBUS_TARGET_PORT', 502);

const CLOSE_TARGET_AFTER_REQUEST = true; // true = korte verbinding per call, false = persistente sessie

const REQUEST_TIMEOUT_MS = 3000;
const CONNECT_TIMEOUT_MS = 3000;
const RETRY_DELAY_MS = 5000;
const WATCHDOG_INTERVAL_MS = 30000;

const MAX_ADU_LENGTH = 260;   // Modbus TCP ADU-maximum
const MIN_LENGTH_FIELD = 2;   // unit id + function code
const MAX_CONNECTIONS = 8;    // gelijktijdige management-clients
const MAX_QUEUE_DEPTH = 2;    // in-flight + wachtend per management-client
const DEBUG_PAYLOADS = false; // true = volledige hex naar output 1

// Leeg = alle clients. Zet hier management-IP's om de repeater af te schermen.
const ALLOWED_CLIENT_IPS = [
    // '10.0.0.20',
];

const STATES = { IDLE: 'idle', STARTING: 'starting', LISTENING: 'listening', RESTARTING: 'restarting' };

// ==== Helpers ====
function hex(buf) {
    if (!buf || buf.length === 0) return '';
    const parts = buf.toString('hex').match(/.{1,2}/g);
    return parts ? parts.join(' ') : '';
}

function parseMbap(buf) {
    if (buf.length < 8) return { error: 'buffer te kort voor MBAP header (' + buf.length + ' bytes)' };
    return {
        transactionId: buf.readUInt16BE(0),
        protocolId: buf.readUInt16BE(2),
        length: buf.readUInt16BE(4),
        unitId: buf.readUInt8(6),
        functionCode: buf.readUInt8(7),
        exception: (buf.readUInt8(7) & 0x80) !== 0
    };
}

function normalizeIp(addr) {
    if (!addr) return '';
    if (addr.indexOf('::ffff:') === 0) return addr.slice(7);
    return addr;
}

function isClientAllowed(sock) {
    if (!ALLOWED_CLIENT_IPS.length) return true;
    return ALLOWED_CLIENT_IPS.indexOf(normalizeIp(sock.remoteAddress)) !== -1;
}

function closeSocket(sock) {
    if (!sock) return;
    try {
        if (typeof sock.destroy === 'function') sock.destroy();
        else if (typeof sock.end === 'function') sock.end();
    } catch (e) {
        node.warn('Kon socket niet sluiten: ' + e.message);
    }
}

function getSocketSet() {
    let set = context.get('sockets');
    if (!set || typeof set.add !== 'function') {
        set = new Set();
        context.set('sockets', set);
    }
    return set;
}

function trackSocket(sock) {
    if (!sock) return;
    const sockets = getSocketSet();
    sockets.add(sock);
    sock.once('close', function () { sockets.delete(sock); });
}

function hardenSocket(sock) {
    try {
        sock.setNoDelay(true);
        sock.setKeepAlive(true, 10000);
    } catch (e) { /* ignore */ }
    trackSocket(sock);
}

function snapshotAndDestroySockets() {
    const sockets = getSocketSet();
    const snapshot = [];
    sockets.forEach(function (sock) { snapshot.push(sock); });
    sockets.clear();
    snapshot.forEach(closeSocket);
}

function clearRestartTimer() {
    const t = context.get('restartTimer');
    if (t) clearTimeout(t);
    context.set('restartTimer', null);
}

function sendStatus(level, message, extra) {
    const statusMsg = {
        topic: 'repeater-status',
        payload: Object.assign({ level: level, message: message, time: new Date().toISOString() }, extra || {})
    };
    node.send([null, statusMsg]);
    const short = message.length > 80 ? message.slice(0, 77) + '...' : message;
    if (level === 'error') {
        node.error(message);
        node.status({ fill: 'red', shape: 'ring', text: short });
    } else if (level === 'warn') {
        node.warn(message);
        node.status({ fill: 'yellow', shape: 'ring', text: short });
    } else {
        node.status({ fill: 'green', shape: 'dot', text: short });
    }
}

function emitTraffic(topic, frame) {
    const mbap = parseMbap(frame);
    const out = { topic: topic, mbap: mbap };
    if (DEBUG_PAYLOADS) {
        out.payload = frame;
        out.raw = hex(frame);
    } else {
        out.payload = {
            bytes: frame.length,
            transactionId: mbap.transactionId,
            unitId: mbap.unitId,
            functionCode: mbap.functionCode,
            exception: mbap.exception
        };
    }
    node.send([out, null]);
}

function createFramer(onFrame, onError) {
    let buf = Buffer.alloc(0);
    return {
        push: function (chunk) {
            if (!chunk || chunk.length === 0) return;
            buf = Buffer.concat([buf, chunk]);
            while (true) {
                if (buf.length < 6) return;
                const lengthField = buf.readUInt16BE(4);
                const frameLen = 6 + lengthField;
                if (lengthField < MIN_LENGTH_FIELD || frameLen > MAX_ADU_LENGTH) {
                    buf = Buffer.alloc(0);
                    onError('ongeldige MBAP length ' + lengthField + ' (max ADU ' + MAX_ADU_LENGTH + ')');
                    return;
                }
                if (buf.length < frameLen) return;
                const frame = Buffer.from(buf.subarray(0, frameLen));
                buf = buf.subarray(frameLen);
                const protocolId = frame.readUInt16BE(2);
                if (protocolId !== 0) {
                    buf = Buffer.alloc(0);
                    onError('ongeldige protocolId ' + protocolId);
                    return;
                }
                onFrame(frame);
            }
        }
    };
}

function closeServer(server) {
    if (!server) return;
    try {
        if (typeof server.closeAllConnections === 'function') server.closeAllConnections();
    } catch (e) { /* ignore */ }
    try { server.close(); } catch (e) { /* ignore */ }
}

function setState(state) {
    context.set('serverState', state);
}

function getState() {
    return context.get('serverState') || STATES.IDLE;
}

function withTargetSlot(fn) {
    let gate = context.get('targetGate');
    if (!gate || typeof gate.then !== 'function') gate = Promise.resolve();
    const run = gate.then(fn, fn);
    context.set('targetGate', run.then(function () { /* slot vrij */ }, function () { /* slot vrij na fout */ }));
    return run;
}

function scheduleRestart(reason) {
    if (getState() === STATES.RESTARTING) return;
    setState(STATES.RESTARTING);
    sendStatus('error', reason + ' — herstart over ' + (RETRY_DELAY_MS / 1000) + 's');
    snapshotAndDestroySockets();
    closeServer(context.get('server'));
    context.set('server', null);
    clearRestartTimer();
    const t = setTimeout(function () {
        setState(STATES.IDLE);
        startServer();
    }, RETRY_DELAY_MS);
    context.set('restartTimer', t);
}

function attachClient(clientSocket) {
    const clientAddr = normalizeIp(clientSocket.remoteAddress) + ':' + clientSocket.remotePort;
    hardenSocket(clientSocket);

    if (!isClientAllowed(clientSocket)) {
        sendStatus('warn', 'Verbinding geweigerd (niet op allowlist): ' + clientAddr);
        closeSocket(clientSocket);
        return;
    }

    sendStatus('info', 'Management verbonden: ' + clientAddr);

    if (!CLOSE_TARGET_AFTER_REQUEST) {
        attachPersistent(clientSocket, clientAddr);
    } else {
        attachPerRequest(clientSocket, clientAddr);
    }
}

function attachPersistent(clientSocket, clientAddr) {
    const targetSocket = new net.Socket();
    hardenSocket(targetSocket);
    let targetReady = false;
    const pending = [];
    let sessionClosed = false;

    function tearDown() {
        if (sessionClosed) return;
        sessionClosed = true;
        closeSocket(targetSocket);
        closeSocket(clientSocket);
    }

    const connectTimer = setTimeout(function () {
        if (!targetReady) {
            sendStatus('warn', 'Connect-timeout naar slave', { clientAddr: clientAddr, target: TARGET_HOST + ':' + TARGET_PORT });
            tearDown();
        }
    }, CONNECT_TIMEOUT_MS);

    targetSocket.on('error', function (e) {
        sendStatus('error', 'Target error: ' + e.message, { clientAddr: clientAddr, target: TARGET_HOST + ':' + TARGET_PORT });
        tearDown();
    });

    targetSocket.connect(TARGET_PORT, TARGET_HOST, function () {
        clearTimeout(connectTimer);
        if (sessionClosed) return;
        targetReady = true;
        sendStatus('info', 'Verbonden met slave ' + TARGET_HOST + ':' + TARGET_PORT);
        for (let i = 0; i < pending.length; i++) {
            if (!targetSocket.destroyed) targetSocket.write(pending[i]);
        }
        pending.length = 0;
    });

    const clientFramer = createFramer(
        function (frame) {
            emitTraffic('mgmt->slave', frame);
            if (sessionClosed) return;
            if (targetReady && !targetSocket.destroyed) targetSocket.write(frame);
            else if (pending.length < MAX_QUEUE_DEPTH) pending.push(frame);
            else {
                sendStatus('warn', 'Pending-buffer vol vóór slave-connect, sessie gesloten', { clientAddr: clientAddr });
                tearDown();
            }
        },
        function (err) {
            sendStatus('error', 'Framing-fout mgmt->slave: ' + err, { clientAddr: clientAddr });
            tearDown();
        }
    );

    const slaveFramer = createFramer(
        function (frame) {
            emitTraffic('slave->mgmt', frame);
            if (!clientSocket.destroyed) clientSocket.write(frame);
        },
        function (err) {
            sendStatus('error', 'Framing-fout slave->mgmt: ' + err, { clientAddr: clientAddr });
            tearDown();
        }
    );

    clientSocket.on('data', function (data) { clientFramer.push(data); });
    targetSocket.on('data', function (data) { slaveFramer.push(data); });
    clientSocket.on('close', function () {
        sendStatus('info', 'Management gesloten: ' + clientAddr);
        tearDown();
    });
    targetSocket.on('close', function () { tearDown(); });
    clientSocket.on('error', function (e) {
        sendStatus('error', 'Client error: ' + e.message, { clientAddr: clientAddr });
        tearDown();
    });
}

function attachPerRequest(clientSocket, clientAddr) {
    let requestQueue = Promise.resolve();
    let queueDepth = 0;
    let aborted = false;
    const inflight = [];

    function abortSession() {
        aborted = true;
        const open = inflight.slice();
        inflight.length = 0;
        open.forEach(closeSocket);
    }

    function runRequest(frame) {
        return withTargetSlot(function () {
            return new Promise(function (resolve) {
                if (aborted || clientSocket.destroyed) {
                    resolve();
                    return;
                }

                emitTraffic('mgmt->slave', frame);

                const targetSocket = new net.Socket();
                hardenSocket(targetSocket);
                inflight.push(targetSocket);
                let settled = false;
                let wrote = false;

                const finish = function () {
                    if (settled) return;
                    settled = true;
                    clearTimeout(timeoutHandle);
                    const idx = inflight.indexOf(targetSocket);
                    if (idx !== -1) inflight.splice(idx, 1);
                    closeSocket(targetSocket);
                    resolve();
                };

                const timeoutHandle = setTimeout(function () {
                    sendStatus('warn', wrote
                        ? 'Timeout op antwoord van slave (per-request modus)'
                        : 'Connect-timeout naar slave (per-request modus)', {
                        clientAddr: clientAddr,
                        target: TARGET_HOST + ':' + TARGET_PORT
                    });
                    finish();
                }, REQUEST_TIMEOUT_MS);

                targetSocket.on('error', function (e) {
                    sendStatus('error', 'Target error (per-request): ' + e.message, { clientAddr: clientAddr, target: TARGET_HOST + ':' + TARGET_PORT });
                    finish();
                });

                const respFramer = createFramer(
                    function (respFrame) {
                        emitTraffic('slave->mgmt', respFrame);
                        if (!clientSocket.destroyed && !aborted) clientSocket.write(respFrame);
                        finish();
                    },
                    function (err) {
                        sendStatus('error', 'Framing-fout slave->mgmt: ' + err, { clientAddr: clientAddr });
                        finish();
                    }
                );

                targetSocket.on('data', function (chunk) { respFramer.push(chunk); });

                targetSocket.on('close', function () {
                    if (!settled) {
                        sendStatus('warn', 'Slave sloot verbinding vóór een volledig frame', { clientAddr: clientAddr });
                    }
                    finish();
                });

                targetSocket.connect(TARGET_PORT, TARGET_HOST, function () {
                    if (settled || aborted) {
                        closeSocket(targetSocket);
                        return;
                    }
                    wrote = true;
                    targetSocket.write(frame);
                });
            });
        });
    }

    const clientFramer = createFramer(
        function (frame) {
            if (aborted || clientSocket.destroyed) return;
            if (queueDepth >= MAX_QUEUE_DEPTH) {
                sendStatus('warn', 'Queue vol (' + MAX_QUEUE_DEPTH + '), sessie gesloten', { clientAddr: clientAddr });
                closeSocket(clientSocket);
                abortSession();
                return;
            }
            queueDepth += 1;
            requestQueue = requestQueue
                .then(function () { return runRequest(frame); })
                .catch(function (e) {
                    sendStatus('error', 'Request-fout: ' + (e && e.message ? e.message : e), { clientAddr: clientAddr });
                })
                .then(function () { queueDepth -= 1; });
        },
        function (err) {
            sendStatus('error', 'Framing-fout mgmt->slave: ' + err, { clientAddr: clientAddr });
            closeSocket(clientSocket);
            abortSession();
        }
    );

    clientSocket.on('data', function (data) { clientFramer.push(data); });
    clientSocket.on('close', function () {
        abortSession();
        sendStatus('info', 'Management gesloten: ' + clientAddr);
    });
    clientSocket.on('error', function (e) {
        abortSession();
        sendStatus('error', 'Client error: ' + e.message, { clientAddr: clientAddr });
    });
}

function startServer() {
    const state = getState();
    if (state === STATES.STARTING || state === STATES.LISTENING || state === STATES.RESTARTING) {
        return;
    }

    setState(STATES.STARTING);
    clearRestartTimer();

    const previous = context.get('server');
    if (previous) {
        closeServer(previous);
        context.set('server', null);
    }

    let server;
    try {
        server = net.createServer(attachClient);
        server.maxConnections = MAX_CONNECTIONS;

        server.on('error', function (e) {
            scheduleRestart('Server error: ' + e.message);
        });

        server.listen(LISTEN_PORT, LISTEN_HOST, function () {
            setState(STATES.LISTENING);
            const mode = CLOSE_TARGET_AFTER_REQUEST ? 'per-request' : 'persistent';
            const acl = ALLOWED_CLIENT_IPS.length ? ('allowlist ' + ALLOWED_CLIENT_IPS.length + ' IP') : 'geen IP-allowlist';
            sendStatus('info', 'Repeater v3.1 luistert op ' + LISTEN_HOST + ':' + LISTEN_PORT + ' (modus: ' + mode + ', maxConn: ' + MAX_CONNECTIONS + ', ' + acl + ')');
        });

        context.set('server', server);
    } catch (e) {
        context.set('server', null);
        setState(STATES.IDLE);
        scheduleRestart('Kon server niet starten: ' + e.message);
    }
}

startServer();

const watchdog = setInterval(function () {
    const state = getState();
    if (state === STATES.STARTING || state === STATES.RESTARTING) return;
    const server = context.get('server');
    if (!server || !server.listening) {
        sendStatus('warn', 'Watchdog: server luistert niet meer, herstart wordt gestart');
        setState(STATES.IDLE);
        startServer();
    }
}, WATCHDOG_INTERVAL_MS);
context.set('watchdog', watchdog);

finalize:
const watchdog = context.get('watchdog');
const restartTimer = context.get('restartTimer');
const server = context.get('server');
const sockets = context.get('sockets');

if (watchdog) clearInterval(watchdog);
if (restartTimer) clearTimeout(restartTimer);

if (sockets && typeof sockets.forEach === 'function') {
    const snapshot = [];
    sockets.forEach(function (sock) { snapshot.push(sock); });
    sockets.clear();
    snapshot.forEach(function (sock) {
        try {
            if (sock && typeof sock.destroy === 'function') sock.destroy();
        } catch (e) { /* ignore */ }
    });
}

if (server) {
    try {
        if (typeof server.closeAllConnections === 'function') server.closeAllConnections();
    } catch (e) { /* ignore */ }
    try { server.close(); } catch (e) { /* ignore */ }
}

context.set('server', null);
context.set('watchdog', null);
context.set('restartTimer', null);
context.set('sockets', null);
context.set('targetGate', null);
context.set('serverState', 'idle');

