// ==== Instellingen ====
const MIN_LEVEL = 'error';           // 'warn' of 'error' — alles daaronder wordt genegeerd
const DEBOUNCE_MS = 60000;           // minimaal deze tijd tussen twee alerts van hetzelfde type
const IGNORE_MESSAGES_CONTAINING = [ // ruis die je nooit als "echte fout" wilt zien, ook al is het level 'error'
    // voorbeeld: 'ECONNRESET'  -- laat leeg als je alles wilt zien
];

const levelRank = { info: 0, warn: 1, error: 2 };

if (!msg.payload || typeof msg.payload !== 'object') {
    return null; // onverwacht formaat, negeer stilletjes
}

const { level, message } = msg.payload;

// Stap 1: level-filter
if (levelRank[level] === undefined || levelRank[level] < levelRank[MIN_LEVEL]) {
    return null;
}

// Stap 2: bekende ruis eruit filteren
if (IGNORE_MESSAGES_CONTAINING.some(needle => message.includes(needle))) {
    return null;
}

// Stap 3: debounce — voorkom alert-spam bij herhaalde identieke fouten
// Sleutel op basis van message-tekst (zonder tijdstip/adres-specifieke details te hard te binden)
const dedupeKey = message.replace(/\d/g, '#'); // cijfers weg zodat bv. poortnummers niet elke keer een 'nieuwe' fout lijken
const lastSeen = context.get('lastSeen') || {};
const now = Date.now();

if (lastSeen[dedupeKey] && (now - lastSeen[dedupeKey]) < DEBOUNCE_MS) {
    // Zelfde soort fout te snel opnieuw — onderdruk, maar hou een teller bij
    const suppressedCount = context.get('suppressedCount') || {};
    suppressedCount[dedupeKey] = (suppressedCount[dedupeKey] || 0) + 1;
    context.set('suppressedCount', suppressedCount);
    return null;
}

lastSeen[dedupeKey] = now;
context.set('lastSeen', lastSeen);

// Stap 4: als er eerder onderdrukte meldingen waren, vermeld dat erbij
const suppressedCount = context.get('suppressedCount') || {};
const suppressedForThis = suppressedCount[dedupeKey] || 0;
if (suppressedForThis > 0) {
    msg.payload.suppressedRepeats = suppressedForThis;
    suppressedCount[dedupeKey] = 0;
    context.set('suppressedCount', suppressedCount);
}

// Stap 5: doorlaten als échte, relevante fout
msg.topic = 'MODBUS REPEATER ALERT';
return msg;
